CREATE OR REPLACE FUNCTION public.start_lifeform_building(p_planet_id uuid,p_building_id text) RETURNS jsonb LANGUAGE plpgsql AS $function$ DECLARE v_def public.lifeform_building_definitions%ROWTYPE;v_lf text;v_level integer:=0;v_target integer;v_id uuid;v_m numeric;v_c numeric;v_d numeric; BEGIN SELECT * INTO v_def FROM public.lifeform_building_definitions WHERE id=p_building_id;IF NOT FOUND THEN RAISE EXCEPTION 'Unknown lifeform building %',p_building_id;END IF;SELECT lifeform_id INTO v_lf FROM public.planet_lifeforms WHERE planet_id=p_planet_id AND active=true;IF v_lf IS NULL OR v_lf<>v_def.lifeform_id THEN RAISE EXCEPTION 'Active lifeform does not match building';END IF;SELECT COALESCE(MAX(level),0) INTO v_level FROM public.planet_lifeform_buildings WHERE planet_id=p_planet_id AND building_id=p_building_id;v_target:=v_level+1;IF v_target>v_def.max_level THEN RAISE EXCEPTION 'Max level reached';END IF;SELECT metal,crystal,deuterium INTO v_m,v_c,v_d FROM public.calculate_lifeform_building_cost(p_building_id,v_target);PERFORM 1 FROM public.planet_resources WHERE planet_id=p_planet_id AND metal>=v_m AND crystal>=v_c AND deuterium>=v_d FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Insufficient resources for % level %',p_building_id,v_target;END IF;UPDATE public.planet_resources SET metal=metal-v_m,crystal=crystal-v_c,deuterium=deuterium-v_d,updated_at=now() WHERE planet_id=p_planet_id;INSERT INTO public.planet_lifeform_buildings(planet_id,building_id,level) VALUES(p_planet_id,p_building_id,v_target) ON CONFLICT(planet_id,building_id) DO UPDATE SET level=EXCLUDED.level,updated_at=now();INSERT INTO public.lifeform_building_queue(planet_id,building_id,target_level,started_at,finishes_at,status) VALUES(p_planet_id,p_building_id,v_target,now(),now(),'COMPLETED') RETURNING id INTO v_id;RETURN jsonb_build_object('queue_id',v_id,'building_id',p_building_id,'level',v_target,'completed',true,'accelerated',true,'cost',jsonb_build_object('metal',v_m,'crystal',v_c,'deuterium',v_d));END;$function$;
CREATE OR REPLACE FUNCTION public.start_lifeform_research(p_planet_id uuid,p_research_id text) RETURNS jsonb LANGUAGE plpgsql AS $function$ DECLARE v_def public.lifeform_research_definitions%ROWTYPE;v_active text;v_level integer:=0;v_target integer;v_id uuid;v_player uuid;v_discovered boolean;v_population numeric;v_previous_slots integer;v_m numeric;v_c numeric;v_d numeric; BEGIN SELECT * INTO v_def FROM public.lifeform_research_definitions WHERE id=p_research_id;IF NOT FOUND THEN RAISE EXCEPTION 'Unknown lifeform research %',p_research_id;END IF;SELECT lifeform_id,player_id INTO v_active,v_player FROM public.planets p JOIN public.planet_lifeforms pl ON pl.planet_id=p.id AND pl.active=true WHERE p.id=p_planet_id;IF v_active IS NULL THEN RAISE EXCEPTION 'No active lifeform';END IF;SELECT COALESCE(bool_or(discovered),false) INTO v_discovered FROM public.player_lifeform_discoveries WHERE player_id=v_player AND lifeform_id=v_def.lifeform_id;IF NOT v_discovered THEN RAISE EXCEPTION 'Lifeform % has not been discovered',v_def.lifeform_id;END IF;SELECT population_t1+population_t2+population_t3 INTO v_population FROM public.planet_lifeforms WHERE planet_id=p_planet_id;IF COALESCE(v_population,0)<public.get_lifeform_research_population_requirement(v_def.slot) THEN RAISE EXCEPTION 'Population %. Required for slot %: %',COALESCE(v_population,0),v_def.slot,public.get_lifeform_research_population_requirement(v_def.slot);END IF;IF v_def.tier>1 THEN SELECT count(*) INTO v_previous_slots FROM public.planet_lifeform_research WHERE planet_id=p_planet_id AND slot BETWEEN ((v_def.tier-1)*6-5) AND ((v_def.tier-1)*6);IF v_previous_slots<6 THEN RAISE EXCEPTION 'Tier % requires all previous 6 research slots',v_def.tier;END IF;END IF;SELECT COALESCE(MAX(level),0) INTO v_level FROM public.planet_lifeform_research WHERE planet_id=p_planet_id AND slot=v_def.slot;v_target:=v_level+1;IF v_target>v_def.max_level THEN RAISE EXCEPTION 'Max level reached';END IF;SELECT metal,crystal,deuterium INTO v_m,v_c,v_d FROM public.calculate_lifeform_research_cost(p_research_id,v_target);PERFORM 1 FROM public.planet_resources WHERE planet_id=p_planet_id AND metal>=v_m AND crystal>=v_c AND deuterium>=v_d FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Insufficient resources for % level %',p_research_id,v_target;END IF;UPDATE public.planet_resources SET metal=metal-v_m,crystal=crystal-v_c,deuterium=deuterium-v_d,updated_at=now() WHERE planet_id=p_planet_id;INSERT INTO public.planet_lifeform_research(planet_id,slot,research_id,level) VALUES(p_planet_id,v_def.slot,p_research_id,v_target) ON CONFLICT(planet_id,slot) DO UPDATE SET research_id=EXCLUDED.research_id,level=EXCLUDED.level,updated_at=now();INSERT INTO public.lifeform_research_queue(planet_id,research_id,target_level,started_at,finishes_at,status) VALUES(p_planet_id,p_research_id,v_target,now(),now(),'COMPLETED') RETURNING id INTO v_id;RETURN jsonb_build_object('queue_id',v_id,'research_id',p_research_id,'slot',v_def.slot,'level',v_target,'completed',true,'accelerated',true,'cost',jsonb_build_object('metal',v_m,'crystal',v_c,'deuterium',v_d));END;$function$;